function pvpShareUrl() {
    var base = 'https://bitcoineducation.quest/#pvp';
    if (typeof shareDeepUrl === 'function') return shareDeepUrl(base);
    return base;
}
function pvpCopyShareLink(friend) {
    var url = pvpShareUrl();
    var box = document.getElementById('pvpShareLink');
    if (box) box.textContent = url;
    var done = function() {
        if (typeof showToast === 'function') showToast(friend ? '📋 Link copied! Send it to a friend!' : '📋 Link copied!');
    };
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(url).then(done).catch(function() {});
    else done();
    return url;
}
